const xml = $input.first().json.data;
const match = xml.match(/<value><int>(\d+)<\/int><\/value>/);
const uid = match ? parseInt(match[1]) : null;
if (!uid) throw new Error('Odoo authenticate failed, uid not found. XML: ' + xml.slice(0,300));
return [{ json: { uid } }];

const b = $node['Webhook1'].json.body;
const lessonTitle = b.lessonTitle || '';
const courseName  = b.courseName  || '';
const completed   = parseInt(b.completedCount) || 0;
const total       = parseInt(b.totalCount)     || 0;
const pct         = parseInt(b.progressPct)    || 0;
const date        = (b.timestamp || new Date().toISOString()).slice(0,10);

function xmlEsc(s){ return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const note = `[${date}] ✅ Hoàn thành: ${xmlEsc(lessonTitle)}&lt;br/&gt;📚 Khóa: ${xmlEsc(courseName)}&lt;br/&gt;📊 Tiến độ: ${completed}/${total} bài (${pct}%)`;

const email = (b.email || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const name  = xmlEsc(b.name  || '');
const phone = xmlEsc(b.phone || '');
const courseNameEsc = xmlEsc(courseName);

return [{ json: { note, email, name, phone, courseNameEsc } }];

const xml = $input.first().json.data;
const match = xml.match(/<value><int>(\d+)<\/int><\/value>/);
const leadId = match ? parseInt(match[1]) : null;
const found = leadId !== null && leadId > 0;
return [{ json: { leadId, found } }];

const xml = $input.first().json.data;
const match = xml.match(/<value><int>(\d+)<\/int><\/value>/);
const newLeadId = match ? parseInt(match[1]) : null;
if (!newLeadId) throw new Error('Create lead failed. XML: ' + xml.slice(0,300));
return [{ json: { newLeadId } }];
